// ============================================================
// aggregate_and_format — Daily Report Code Node
// Reads all 7 upstream query results and builds HTML + WhatsApp
// ============================================================

// --- Helper: safe array from upstream node ---
function safeAll(nodeName) {
  try {
    const items = $(nodeName).all();
    // Filter out empty placeholder rows (alwaysOutputData produces [{json:{}}])
    return items.filter(i => i.json && Object.keys(i.json).length > 0);
  } catch (e) {
    return [];
  }
}

function safeFirst(nodeName) {
  try {
    const item = $(nodeName).first();
    return item ? item.json : {};
  } catch (e) {
    return {};
  }
}

// --- Read upstream data ---
const healthViolations = safeAll('query_health_violations');
const planFailures = safeAll('query_plan_failures');
const newUsersData = safeFirst('query_new_users');
const engagementData = safeFirst('query_engagement');
const churnRisk = safeAll('query_churn_risk');
const neverCompleted = safeAll('query_never_completed');
const abandonedKyc = safeAll('query_abandoned_kyc');

// --- Metrics with defensive defaults ---
const newUsers = Number(newUsersData.new_users_count) || 0;
const kycCompletions = Number(newUsersData.kyc_completions_count) || 0;
const plansGenerated = Number(newUsersData.plans_generated_count) || 0;
const totalUsers = Number(newUsersData.total_users) || 0;
const totalActivePlans = Number(newUsersData.total_active_plans) || 0;

const completedSessions = Number(engagementData.completed_sessions) || 0;
const totalScheduled = Number(engagementData.total_scheduled_sessions) || 0;
const completionRate = Number(engagementData.completion_rate_pct) || 0;
const activeYesterday = Number(engagementData.active_users_yesterday) || 0;
const completedYesterday = Number(engagementData.completed_users_yesterday) || 0;

const healthViolationCount = healthViolations.length;
const planFailureCount = planFailures.length;
const churnRiskCount = churnRisk.length;
const neverCompletedCount = neverCompleted.length;
const abandonedKycCount = abandonedKyc.length;

// --- Report date ---
const now = DateTime.now().setZone('America/Bogota');
const reportDate = now.toFormat('dd/MM/yyyy');
const reportDateLong = now.toFormat('dd MMMM yyyy', { locale: 'es' });
const subject = `Reporte Diario GymBot — ${reportDate}`;

// --- Completion rate color ---
let rateColor = '#e63946';
let rateBg = '#fee2e2';
if (completionRate >= 70) { rateColor = '#2d6a4f'; rateBg = '#d1fae5'; }
else if (completionRate >= 40) { rateColor = '#b45309'; rateBg = '#fff3cd'; }

// --- Helper: escape HTML entities ---
function escapeHtml(str) {
  if (str === null || str === undefined) return '-';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// --- Helper: build HTML table ---
function htmlTable(headers, rows) {
  if (rows.length === 0) return '<p style="color:#6b7280;font-style:italic;margin:8px 0;">Sin registros</p>';
  let html = '<table style="width:100%;border-collapse:collapse;font-size:13px;margin:8px 0;">';
  html += '<tr>' + headers.map(h => `<th style="background:#f1f3f5;padding:8px 10px;text-align:left;border:1px solid #dee2e6;font-weight:600;">${escapeHtml(h)}</th>`).join('') + '</tr>';
  rows.forEach(r => {
    html += '<tr>' + r.map(c => `<td style="padding:8px 10px;border:1px solid #dee2e6;">${escapeHtml(c)}</td>`).join('') + '</tr>';
  });
  html += '</table>';
  return html;
}

// --- Build HTML ---
let html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:0;background:#f5f5f5;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" style="width:100%;background:#f5f5f5;">
<tr><td align="center" style="padding:20px;">
<table style="width:100%;max-width:700px;background:#ffffff;border-radius:8px;overflow:hidden;">

<!-- HEADER -->
<tr><td style="background:#1a1a2e;padding:24px 32px;">
  <h1 style="color:#ffffff;margin:0;font-size:22px;">Reporte Diario GymBot</h1>
  <p style="color:#a0a0c0;margin:6px 0 0;font-size:14px;">${reportDateLong}</p>
</td></tr>

<tr><td style="padding:24px 32px;">`;

// --- SECTION 1: ACCION INMEDIATA (only if alerts exist) ---
if (healthViolationCount > 0 || planFailureCount > 0) {
  html += `
  <div style="border:2px solid #e63946;border-radius:6px;padding:16px;margin-bottom:24px;background:#fee2e2;">
    <h2 style="color:#e63946;margin:0 0 12px;font-size:18px;">ACCION INMEDIATA</h2>`;

  if (healthViolationCount > 0) {
    html += `<h3 style="margin:12px 0 6px;font-size:14px;color:#991b1b;">Violaciones de Salud (${healthViolationCount})</h3>`;
    html += htmlTable(
      ['Usuario', 'Telefono', 'Salud', 'Ejercicio', 'Dia', 'Semana', 'Violacion'],
      healthViolations.map(v => [
        v.json.full_name, v.json.full_phone_number, v.json.health_status,
        v.json.spanish_name, v.json.day_name, v.json.week, v.json.violation_type
      ])
    );
  }

  if (planFailureCount > 0) {
    html += `<h3 style="margin:12px 0 6px;font-size:14px;color:#991b1b;">Fallos de Generacion (${planFailureCount})</h3>`;
    html += htmlTable(
      ['Tipo', 'Usuario', 'WhatsApp', 'Fecha', 'Estado Plan'],
      planFailures.map(v => [
        v.json.failure_type, v.json.full_name, v.json.whatsapp_id,
        v.json.submission_date ? String(v.json.submission_date).substring(0, 10) : '-',
        v.json.plan_status || '-'
      ])
    );
  }

  html += '</div>';
}

// --- SECTION 2: NUEVOS USUARIOS & ONBOARDING ---
html += `
  <div style="border:1px solid #dee2e6;border-radius:6px;padding:16px;margin-bottom:24px;">
    <h2 style="color:#1a1a2e;margin:0 0 12px;font-size:18px;">Nuevos Usuarios &amp; Onboarding</h2>
    <table style="width:100%;border-collapse:collapse;font-size:14px;margin:8px 0;">
      <tr>
        <td style="padding:10px;background:#d1fae5;border-radius:4px;text-align:center;width:33%;">
          <div style="font-size:28px;font-weight:700;color:#2d6a4f;">${newUsers}</div>
          <div style="font-size:12px;color:#6b7280;margin-top:4px;">Nuevos usuarios (24h)</div>
        </td>
        <td style="padding:10px;background:#d1fae5;border-radius:4px;text-align:center;width:33%;">
          <div style="font-size:28px;font-weight:700;color:#2d6a4f;">${kycCompletions}</div>
          <div style="font-size:12px;color:#6b7280;margin-top:4px;">KYC completados</div>
        </td>
        <td style="padding:10px;background:#d1fae5;border-radius:4px;text-align:center;width:33%;">
          <div style="font-size:28px;font-weight:700;color:#2d6a4f;">${plansGenerated}</div>
          <div style="font-size:12px;color:#6b7280;margin-top:4px;">Planes generados</div>
        </td>
      </tr>
    </table>
    <table style="width:100%;border-collapse:collapse;font-size:13px;margin:12px 0 0;">
      <tr>
        <td style="padding:6px 10px;color:#6b7280;">Total usuarios plataforma:</td>
        <td style="padding:6px 10px;font-weight:600;text-align:right;">${totalUsers}</td>
      </tr>
      <tr>
        <td style="padding:6px 10px;color:#6b7280;">Planes activos:</td>
        <td style="padding:6px 10px;font-weight:600;text-align:right;">${totalActivePlans}</td>
      </tr>
    </table>`;

if (abandonedKycCount > 0) {
  html += `<h3 style="margin:16px 0 6px;font-size:14px;color:#b45309;">KYC Abandonados (${abandonedKycCount})</h3>`;
  html += `<div style="background:#fff3cd;border-radius:4px;padding:8px;">`;
  html += htmlTable(
    ['WhatsApp ID', 'Mensajes Enviados'],
    abandonedKyc.map(v => [v.json.whatsapp_id, v.json.message_count])
  );
  html += '</div>';
}

html += '</div>';

// --- SECTION 3: ENGAGEMENT ---
html += `
  <div style="border:1px solid #dee2e6;border-radius:6px;padding:16px;margin-bottom:24px;">
    <h2 style="color:#1a1a2e;margin:0 0 12px;font-size:18px;">Engagement (7 dias)</h2>
    <div style="text-align:center;padding:16px;background:${rateBg};border-radius:6px;margin-bottom:12px;">
      <div style="font-size:42px;font-weight:700;color:${rateColor};">${completionRate}%</div>
      <div style="font-size:13px;color:#6b7280;margin-top:4px;">Tasa de completamiento</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <tr>
        <td style="padding:6px 10px;color:#6b7280;">Sesiones completadas / programadas:</td>
        <td style="padding:6px 10px;font-weight:600;text-align:right;">${completedSessions} / ${totalScheduled}</td>
      </tr>
      <tr>
        <td style="padding:6px 10px;color:#6b7280;">Usuarios activos ayer:</td>
        <td style="padding:6px 10px;font-weight:600;text-align:right;">${activeYesterday}</td>
      </tr>
      <tr>
        <td style="padding:6px 10px;color:#6b7280;">Completaron ayer:</td>
        <td style="padding:6px 10px;font-weight:600;text-align:right;">${completedYesterday}</td>
      </tr>
    </table>
  </div>`;

// --- SECTION 4: RIESGO DE ABANDONO ---
html += `
  <div style="border:1px solid #dee2e6;border-radius:6px;padding:16px;margin-bottom:24px;">
    <h2 style="color:#1a1a2e;margin:0 0 12px;font-size:18px;">Riesgo de Abandono</h2>`;

if (churnRiskCount > 0) {
  html += `<h3 style="margin:8px 0 6px;font-size:14px;color:#b45309;">2+ sesiones perdidas (${churnRiskCount} usuarios)</h3>`;
  html += `<div style="background:#fff3cd;border-radius:4px;padding:8px;">`;
  html += htmlTable(
    ['Usuario', 'Telefono', 'Sesiones Perdidas', 'Estado', 'Semana'],
    churnRisk.map(v => [
      v.json.full_name, v.json.full_phone_number, v.json.recent_misses,
      v.json.inactivity_status, v.json.current_week
    ])
  );
  html += '</div>';
} else {
  html += '<p style="color:#2d6a4f;margin:8px 0;">Sin usuarios en riesgo de abandono</p>';
}

if (neverCompletedCount > 0) {
  html += `<h3 style="margin:16px 0 6px;font-size:14px;color:#991b1b;">Nunca completaron (plan activo &gt;3 dias) — ${neverCompletedCount} usuarios</h3>`;
  html += `<div style="background:#fee2e2;border-radius:4px;padding:8px;">`;
  html += htmlTable(
    ['Usuario', 'Telefono', 'Inicio Plan', 'Esquema', 'Sesiones Programadas'],
    neverCompleted.map(v => [
      v.json.full_name, v.json.full_phone_number,
      v.json.start_date ? String(v.json.start_date).substring(0, 10) : '-',
      v.json.week_schedule, v.json.total_scheduled
    ])
  );
  html += '</div>';
} else {
  html += '<p style="color:#2d6a4f;margin:8px 0;">Todos los usuarios con plan activo han completado al menos una sesion</p>';
}

html += '</div>';

// --- FOOTER ---
html += `
  <div style="border-top:1px solid #dee2e6;padding:16px 0 0;margin-top:8px;text-align:center;">
    <p style="font-size:11px;color:#9ca3af;margin:0;">Reporte generado automaticamente — ${now.toFormat('dd/MM/yyyy HH:mm')} (America/Bogota)</p>
    <p style="font-size:11px;color:#9ca3af;margin:4px 0 0;">GymBot by Kairos Fit</p>
  </div>

</td></tr>
</table>
</td></tr>
</table>
</body></html>`;

// --- WhatsApp Summary ---
const whatsappMessage = `Reporte Diario GymBot — ${reportDate}

Nuevos: ${newUsers} usuarios | ${plansGenerated} planes generados
KYC abandonados: ${abandonedKycCount} empezaron pero no terminaron
Alertas: ${healthViolationCount} violaciones salud | ${planFailureCount} fallos generacion
Completamiento 7d: ${completionRate}%
Riesgo abandono: ${churnRiskCount} usuarios (2+ sesiones perdidas)

Reporte completo enviado por email`;

return [{ json: { html, whatsappMessage, subject, reportDate } }];
